F('w1d5-1', 'Тӯҳфа барои синф', 'Барои n шогирд тӯҳфа ба нархи c сомонӣ мехаранд. Пули ҷамъшуда s сомонӣ аст (s ≥ n·c). Ҳамагӣ чанд сарф мешавад ва чанд мемонад?', ['n', 'c', 's'], ['n * c', 's - n * c'], ['n*c', 's - n*c'],
  'Як сатр: n, c, s.', 'Ду адад: харҷ ва бақия.', ['20 15 400', '10 10 100', '0 5 50'], lambda r: (lambda n, c: f'{n} {c} {n*c + R(r,0,10**6)}')(R(r,0,1000), R(r,0,10**6)), '{n}·{c} ва {s} − {n}·{c}: {r}')
F('w1d5-2', 'Ҷойҳои холӣ', 'Дар толор q қатор, дар ҳар қатор k ҷой ҳаст. g меҳмон омад (g ≤ q·k). Чанд ҷой холӣ монд?', ['q', 'k', 'g'], 'q * k - g', 'q*k - g',
  'Як сатр: q, k, g.', 'Як адад.', ['10 20 150', '5 5 25', '3 4 0'], lambda r: (lambda a, b: f'{a} {b} {R(r,0,a*b)}')(R(r,1,10**4), R(r,1,10**4)), '{q}·{k} − {g} = {res}')
F('w1d5-3', 'Охири дарс', 'Дарс соати h ва дақиқаи m оғоз шуда, d дақиқа давом мекунад. Дарс соати чанд тамом мешавад? (вақт 24-соата, пас аз 23:59 — 0:00)', ['h', 'm', 'd'],
  ['(h * 60 + m + d) / 60 % 24', '(h * 60 + m + d) % 60'], ['(h*60 + m + d) // 60 % 24', '(h*60 + m + d) % 60'], 'Як сатр: h, m, d (0 ≤ h ≤ 23, 0 ≤ m ≤ 59, 0 ≤ d ≤ 10⁶).', 'Ду адад: соат ва дақиқа.',
  ['14 0 45', '23 30 45', '8 5 0'], lambda r: f'{R(r,0,23)} {R(r,0,59)} {R(r,0,10**6)}', '{h}:{m} + {d} дақ. → {r}')
F('w1d5-4', 'Фоизи оддӣ', 'Шахс s сомонӣ ба бонк гузошт. Ҳар сол p фоиз (аз маблағи аввала) илова мешавад. Пас аз y сол чанд сомонӣ мешавад? Натиҷа = s + s·p·y/100 (қисми бутун).', ['s', 'p', 'y'], 's + s * p * y / 100', 's + s*p*y // 100',
  'Як сатр: s, p, y (0 ≤ s ≤ 10⁶, 0 ≤ p ≤ 100, 0 ≤ y ≤ 100).', 'Як адад.', ['1000 10 2', '500 0 5', '100 7 3'], lambda r: f'{R(r,0,10**6)} {R(r,0,100)} {R(r,0,100)}', '{s} + {s}·{p}·{y}/100 = {r}')
F('w1d5-5', 'Хондани китоб', 'Китоб n саҳифа дорад. Мадина рӯзе k саҳифа мехонад. Китобро дар чанд рӯз тамом мекунад?', ['n', 'k'], '(n + k - 1) / k', '(n + k - 1) // k',
  'Як сатр: n, k (1 ≤ n, k ≤ 10⁹).', 'Як адад.', ['100 30', '90 30', '1 10'], lambda r: f'{R(r,1,10**9)} {R(r,1,10**4)}', '({n} + {k} − 1) / {k} = {r}')
F('w1d5-6', 'Қуттиҳо', 'n дафтарро ба қуттиҳо мегузоранд, дар ҳар қуттӣ k дафтар. Чанд қуттии пурра мешавад ва чанд дафтар берун мемонад?', ['n', 'k'], ['n / k', 'n % k'], ['n // k', 'n % k'],
  'Як сатр: n, k (0 ≤ n ≤ 10⁹, 1 ≤ k ≤ 10⁹).', 'Ду адад.', ['25 10', '30 10', '3 10'], lambda r: f'{R(r,0,10**9)} {R(r,1,1000)}', '{n}/{k} ва {n}%{k}: {r}')
F('w1d5-7', 'Мусобиқаи теннис', 'Дар мусобиқа n бозингар ҳаст. Ҳар кас бо ҳар кас як бор бозӣ мекунад. Ҳамагӣ чанд бозӣ мешавад? (n·(n−1)/2)', ['n'], 'n * (n - 1) / 2', 'n * (n - 1) // 2',
  'Як адад n (1 ≤ n ≤ 10⁹).', 'Як адад.', ['4', '1', '2', '1000000000'], lambda r: str(R(r,1,10**9)), '{n}·({n}−1)/2 = {r}')
F('w1d5-8', 'Дарахтони хиёбон', 'Хиёбон L метр дароз аст. Аз аввал то охир ҳар d метр дарахт мешинонанд (L ба d тақсим мешавад). Чанд дарахт лозим аст?', ['l', 'd'], 'l / d + 1', 'l // d + 1',
  'Як сатр: L, d (1 ≤ d ≤ 10⁶).', 'Як адад.', ['100 10', '5 5', '0 3'], lambda r: (lambda d: f'{d * R(r,0,10**6)} {d}')(R(r,1,10**6)), '{l}/{d} + 1 = {r}')
F('w1d5-9', 'Пули коғазӣ', 'Нархи мол c сомонӣ аст. Харидор танҳо пули 100-сомонӣ дорад. Чанд пул медиҳад ва чанд сомонӣ бақия мегирад?', ['c'], ['(c + 99) / 100', '(c + 99) / 100 * 100 - c'], ['(c + 99) // 100', '(c + 99) // 100 * 100 - c'],
  'Як адад c (1 ≤ c ≤ 10⁹).', 'Ду адад.', ['250', '300', '1'], lambda r: str(R(r,1,10**9)), 'Барои {c}: {r}')
F('w1d5-10', 'Ду роҳ', 'Аз хона то бозор a км, аз бозор то мактаб b км. Суръат v км/соат (a + b ба v тақсим мешавад). Роҳ чанд соат мегирад?', ['a', 'b', 'v'], '(a + b) / v', '(a + b) // v',
  'Як сатр: a, b, v (1 ≤ v ≤ 1000).', 'Як адад.', ['30 30 20', '5 5 10', '0 0 7'], lambda r: (lambda v: f'{v*R(r,0,10**5)} {v*R(r,0,10**5)} {v}')(R(r,1,1000)), '({a} + {b}) / {v} = {r}')

day(1, 6, 'Имтиҳони ҳафтаи 1', 'io', H1, kind='exam')
F('w1e-1', 'Ҷамъ ва ҳосили зарб', 'Се адад a, b, c дода шудаанд. Ҷамъ ва ҳосили зарби онҳоро чоп кунед.', ['a', 'b', 'c'], ['a + b + c', 'a * b * c'], ['a+b+c', 'a*b*c'], 'Як сатр: a, b, c (|x| ≤ 10⁵).', 'Ду адад.',
  ['1 2 3', '-1 5 2', '0 7 9'], lambda r: ' '.join(str(R(r,-10**5,10**5)) for _ in range(3)), 'Ҷамъ ва зарб: {r}')
F('w1e-2', 'Соат ва дақиқа', 'Филм m дақиқа давом мекунад. Онро ба соат ва дақиқа табдил диҳед.', ['m'], ['m / 60', 'm % 60'], ['m // 60', 'm % 60'], 'Як адад m (0 ≤ m ≤ 10⁹).', 'Ду адад.',
  ['135', '60', '7'], lambda r: str(R(r,0,10**6)), '{m} дақ. = {r}')
F('w1e-3', 'Ҷамъи рақамҳои адади сеҳарфа', 'Адади серақама n дода шудааст. Ҷамъи рақамҳои онро ёбед.', ['n'], 'n % 10 + n / 10 % 10 + n / 100', 'n % 10 + n // 10 % 10 + n // 100',
  'Як адад n (100 ≤ n ≤ 999).', 'Як адад.', ['123', '100', '999'], lambda r: str(R(r,100,999)), 'Рақамҳои {n}: ҷамъ {r}')
F('w1e-4', 'Масоҳат ва периметр', 'Росткунҷа бо тарафҳои a ва b. Масоҳат ва периметрро бо фосила чоп кунед.', ['a', 'b'], ['a * b', '2 * (a + b)'], ['a*b', '2*(a+b)'], 'Як сатр: a, b (1 ≤ a, b ≤ 10⁹).', 'Ду адад.',
  ['3 5', '1 1', '10 2'], lambda r: f'{R(r,1,10**9)} {R(r,1,10**9)}', 'S ва P: {r}')
F('w1e-5', 'Сафи шогирдон', 'n шогирд дар қаторҳои k-нафара меистанд. Чанд қатор лозим аст ва дар қатори охир чанд ҷой холӣ мемонад?', ['n', 'k'], ['(n + k - 1) / k', '(n + k - 1) / k * k - n'], ['(n + k - 1) // k', '(n + k - 1) // k * k - n'],
  'Як сатр: n, k (1 ≤ n, k ≤ 10⁹).', 'Ду адад.', ['25 6', '24 6', '1 1'], lambda r: f'{R(r,1,10**9)} {R(r,1,1000)}', 'Барои {n} ва {k}: {r}')
